","zoneId":"z_m"},{"itemId":"i4","zoneId":"z_nm"},{"itemId":"i5","zoneId":"z_m"},{"itemId":"i6","zoneId":"z_nm"}]}', '[{"text":"Metals are shiny and conduct electricity well.","level":1}]', ARRAY['topic:chemistry','subtopic:periodic-table'], 7, 9, 2, 100, null, 'published', false, 1, '2026-08-17 21:19:08.514+00', '2026-08-17 21:26:52.291+00', '{"review":{"note":"Batch 1 content-bank question approved","state":"approved","version":1,"reviewedAt":"2026-08-17T21:26:51.734Z","submittedAt":"2026-08-17T21:26:51.217Z","reviewerAdminId":"a051d17f-a273-4ffb-b79f-b1bc435322c6","submittedByAdminId":"ed8843ee-f598-4966-aae1-f5ebf481af58"},"feedback":{"correct":"Correct — the explanation above shows why.","incorrect":"Not quite. Read the explanation below and try again."},"authoring":{"authorType":"import","contentHash":"f3c8f9a6166f534165d9b218183ede8a726adcea97942ed1f7780b134100afbe","authorSource":"stem-quest-task-5.14-batch-1-science","createdByAdminId":"ed8843ee-f598-4966-aae1-f5ebf481af58"},"objective":"Classify elements as metals or non-metals."}'), (382, 1, 3, 4, 'Sort each body system into the job it does.', null, 'The circulatory system transports blood, the respiratory system exchanges gases, the digestive system breaks down food, the nervous system sends signals and the skeletal system supports the body.', '{"items":[{"id":"i1","label":"Circulatory"},{"id":"i2","label":"Respiratory"},{"id":"i3","label":"Digestive"},{"id":"i4","label":"Nervous"},{"id":"i5","label":"Skeletal"}],"shuffle":true,"categories":[{"id":"c_blood","label":"Transports blood"},{"id":"c_gas","label":"Gas exchange"},{"id":"c_food","label":"Breaks down food"},{"id":"c_sig","label":"Sends signals"},{"id":"c_sup","label":"Supports the body"}],"schemaVersion":"1.0"}', '{"assignments":[{"itemId":"i1","categoryId":"c_blood"},{"itemId":"i2","categoryId":"c_gas"},{"itemId":"i3","categoryId":"c_food"},{"itemId":"i4","categoryId":"c_sig"},{"itemId":"i5","categoryId":"c_sup"}]}', '[{"text":"Read the job first