"i3","label":"Populations evolve over generations"},{"id":"i4","label":"Species that cannot adapt may go extinct"},{"id":"i5","label":"Evolution happens overnight"}],"shuffle":true,"categories":[{"id":"c_t","label":"True"},{"id":"c_f","label":"False"}],"schemaVersion":"1.0"}', '{"assignments":[{"itemId":"i1","categoryId":"c_t"},{"itemId":"i2","categoryId":"c_f"},{"itemId":"i3","categoryId":"c_t"},{"itemId":"i4","categoryId":"c_t"},{"itemId":"i5","categoryId":"c_f"}]}', '[{"text":"Ask: does this happen to a whole population across generations?","level":1}]', ARRAY['topic:life','subtopic:evolution-ecosystems'], 8, 11, 3, 100, null, 'published', false, 1, '2026-08-17 21:19:20.341+00', '2026-08-17 21:27:18.019+00', '{"review":{"note":"Batch 1 content-bank question approved","state":"approved","version":1,"reviewedAt":"2026-08-17T21:27:17.508Z","submittedAt":"2026-08-17T21:27:16.912Z","reviewerAdminId":"a051d17f-a273-4ffb-b79f-b1bc435322c6","submittedByAdminId":"ed8843ee-f598-4966-aae1-f5ebf481af58"},"feedback":{"correct":"Correct — the explanation above shows why.","incorrect":"Not quite. Read the explanation below and try again."},"authoring":{"authorType":"import","contentHash":"da93fd1a5ee0608364e07a2f8a0660274b91efc0ad73a7a7524cd020028655c3","authorSource":"stem-quest-task-5.14-batch-1-science","createdByAdminId":"ed8843ee-f598-4966-aae1-f5ebf481af58"},"objective":"Evaluate statements about evolution."}'), (401, 1, 4, 3, 'Arrange the steps of the rock cycle in order.', null, 'Weathering breaks rocks, erosion moves the fragments, deposition drops them and compaction forms sedimentary rock.', '{"items":[{"id":"o1","label":"Deposition"},{"id":"o2","label":"Erosion"},{"id":"o3","label":"Weathering"},{"id":"o4","label":"Compaction"}],"shuffle":true,"schemaVersion":"1.0"}', '{"order":["o3","o2","o1","o4"]}', '[{"text":"Breaking comes before moving, which comes before settling.","level":1}]', ARRAY['topic:earth-space','subtopic:rock-cycle'], 8, 11, 2, 100, null, 'published